/* =====================================================================
   PAGE SCRIPTS, SERVED MINIFIED -- which files, where they go, what the loader is told.
   ---------------------------------------------------------------------
   The commented source stays canonical: humans read it, tests read it, and server rendering
   (api/lib/render-core.mjs) runs it. A route's page scripts are also served from a built copy,
   js/min/<same path under js/>, so a visitor downloads minified code (owner decision 2026-10-20,
   W5-MIN, after /account measured +42.8 KB gz and /explore over R2: docs/cms-architecture.md,
   Budget). scripts/build-ark-vendor.cjs writes the copies (npm run build:ark) and refuses drift
   (npm run check:ark / check:pages), the same way it already treats js/ark/blocks.js. This module
   is the part of that build that knows the SITE: it is shared by the build and its test so the
   set of files is derived once.

   WHICH FILES -- derived, never listed. The catalog (js/pages/catalog.js, loaded the way
   scripts/lib/site-routes.mjs loads it) names every script the page loader fetches. Of those, a
   file is built unless one of these says it should not be:
     - it lives where another pipeline owns it: js/vendor/ (third-party code as released: Three.js), js/ark/vendor/ and js/admin/ (the Ark bundles,
       the editor and the Auth Kit bundles are esbuild output already), or js/content/articles/
       (written by the CMS publisher: a build step beside it would leave a published article's
       served copy stale until someone rebuilt, so an article is always served as saved);
     - its first lines say it is generated ("Generated by/from ...", "do not edit": the glossary,
       the registry snapshot, the resolver algebra, the reference text, js/ark/blocks.js, ...):
       a generator owns its bytes, so a generated file is minified, if at all, where it is made;
     - the copy as shipped (provenance header and map comment included) is not under 95% of the
       source: it already is minified (js/ark/ml-dsa.js is an esbuild bundle) or it is tiny, so a
       second copy would cost a request path and a map for nothing.
   Everything else is built. A catalog script that is not built is served as its source: the
   loader falls back to the source path for any file the manifest does not list, so a missing or
   exempt file can never break a route.

   WHAT THE LOADER IS TOLD -- js/min/manifest.js, `ArkUI.minScripts = { "pages/account": "<8 hex>" }`:
   the files that have a built copy, each with the hash of that copy's bytes. js/ark/page-loader.js
   requests js/min/<key>.js?v=<hash>, so a copy's URL changes exactly when its content does.
   index.html loads the manifest with ?v=<hash of the manifest>, stamped by the build (a hand
   change to that tag, like a hand change to any output, is drift).

   SOURCE MAPS -- js/min/<key>.js.map, without sourcesContent: the map names the source file, which
   the site serves, so devtools shows the commented source and an error points at its line.
   ===================================================================== */
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');

const MIN_DIR = 'js/min';
const MANIFEST = MIN_DIR + '/manifest.js';
const INDEX_HTML = 'index.html';
/* The script tag index.html carries for the manifest; the build rewrites its ?v=. */
const MANIFEST_TAG = /(<script src="js\/min\/manifest\.js\?v=)([0-9a-f]{8})(" defer><\/script>)/;
const TARGET = 'es2020'; // the floor the pages already need: they use ?. and ??
/* js/vendor/ is third-party code kept as released: Three.js (js/vendor/three-r180-defxn.js, 724 KB) is already minified, and the 3D world
   loads it by path (js/world/world-host.js), not through a route. Should a route ever list it, it is served as written. */
const OTHER_PIPELINES = ['js/ark/vendor/', 'js/admin/', 'js/vendor/', 'js/content/articles/', MIN_DIR + '/'];
const GENERATED_HEADER = /\b(?:generated (?:by|from)|do not edit)\b/i;
const WORTH_BUILDING = 0.95; // built only when the minified copy is under this share of the source

const sha256 = (bytes) => crypto.createHash('sha256').update(bytes).digest('hex');

/* The real catalog, loaded the way scripts/lib/site-routes.mjs loads it (manifests first: the
   theory pages are derived from them), in a vm with the few globals the files touch. */
function loadCatalog(root) {
  const context = vm.createContext({ ArkUI: {}, ArkCopy: { text: (key) => key }, document: { write() {} }, console });
  const load = (file) => vm.runInContext(fs.readFileSync(path.join(root, file), 'utf8'), context, { filename: file });
  load('js/content/manifest.js');
  load('js/content/manifests/index.js');
  for (const id of context.ArkManifestIds) load('js/content/manifests/' + id + '.js');
  for (const file of ['js/content/learnings.js', 'js/content/article-index.js', 'js/content/resolutions.js', 'js/content/site-pages.js', 'js/pages/catalog.js']) load(file);
  return context.ArkUI.pageCatalog;
}

/* Every script the page loader can fetch for a catalog route, once, sorted. */
function catalogScripts(root) {
  const scripts = new Set();
  for (const entry of Object.values(loadCatalog(root))) for (const script of entry.scripts) scripts.add(script);
  return [...scripts].sort();
}

/* js/pages/account.js -> pages/account (the manifest's key). */
const keyOf = (script) => script.replace(/^js\//, '').replace(/\.js$/, '');
const servedPath = (script) => MIN_DIR + '/' + keyOf(script) + '.js';

function header(script) {
  return '/* Generated by scripts/build-ark-vendor.cjs from ' + script + ' (minified). Do not edit: edit ' + script + ', then npm run build:ark. */';
}

/* One script's built copy and its map, or the reason it is served as written. */
function minify(root, script) {
  const esbuild = require('esbuild');
  const text = fs.readFileSync(path.join(root, script), 'utf8');
  const out = servedPath(script);
  const pipeline = OTHER_PIPELINES.find((dir) => script.startsWith(dir));
  if (pipeline) return { script, exempt: 'built by another pipeline (' + pipeline + ')' };
  if (GENERATED_HEADER.test(text.slice(0, 400))) return { script, exempt: 'generated: its generator owns its bytes' };
  const result = esbuild.transformSync(text, {
    loader: 'js', minify: true, legalComments: 'none', target: TARGET,
    sourcemap: 'external', sourcesContent: false,
    sourcefile: path.posix.relative(path.posix.dirname(out), script),
    banner: header(script),
  });
  const code = result.code.replace(/\n$/, '') + '\n//# sourceMappingURL=' + path.posix.basename(out) + '.map\n';
  // The copy as shipped (its provenance header and map comment included) against the source.
  if (Buffer.byteLength(code) >= Buffer.byteLength(text) * WORTH_BUILDING) return { script, exempt: 'nothing to gain: the copy, header and map comment included, is not under 95% of the source (already minified, or tiny)' };
  return { script, out, code: Buffer.from(code), map: Buffer.from(JSON.stringify(JSON.parse(result.map)) + '\n') };
}

/* Everything the build writes for page scripts: { outputs: [{ out, bytes }], exempt: [{ script, exempt }],
   manifest } -- outputs in a stable order, the manifest last, then index.html with its stamp. */
function plan(root) {
  const built = [], exempt = [];
  for (const script of catalogScripts(root)) {
    const result = minify(root, script);
    (result.exempt ? exempt : built).push(result);
  }
  const hashes = {};
  const outputs = [];
  for (const item of built) {
    outputs.push({ out: item.out, bytes: item.code }, { out: item.out + '.map', bytes: item.map });
    hashes[keyOf(item.script)] = sha256(item.code).slice(0, 8);
  }
  const manifest = Buffer.from(
    '/* Generated by scripts/build-ark-vendor.cjs (scripts/lib/page-scripts.cjs says what is listed). Do not edit. */\n' +
    'ArkUI.minScripts=' + JSON.stringify(hashes) + ';\n');
  outputs.push({ out: MANIFEST, bytes: manifest });
  const html = fs.readFileSync(path.join(root, INDEX_HTML), 'utf8');
  if (!MANIFEST_TAG.test(html)) throw new Error(INDEX_HTML + ' has no <script src="js/min/manifest.js?v=<8 hex>" defer> tag: add it before js/ark/page-loader.js, then npm run build:ark stamps it.');
  outputs.push({ out: INDEX_HTML, bytes: Buffer.from(html.replace(MANIFEST_TAG, '$1' + sha256(manifest).slice(0, 8) + '$3')) });
  return { outputs, exempt, hashes, manifest };
}

/* Files under js/min/ that no output names (a script left the catalog, or became exempt). */
function orphans(root, outputs) {
  const named = new Set(outputs.map((output) => output.out));
  const found = [];
  (function walk(dir) {
    const full = path.join(root, dir);
    if (!fs.existsSync(full)) return;
    for (const entry of fs.readdirSync(full, { withFileTypes: true })) {
      const rel = dir + '/' + entry.name;
      if (entry.isDirectory()) walk(rel);
      else if (!named.has(rel)) found.push(rel);
    }
  })(MIN_DIR);
  return found.sort();
}

module.exports = { MIN_DIR, MANIFEST, INDEX_HTML, MANIFEST_TAG, loadCatalog, catalogScripts, keyOf, servedPath, minify, plan, orphans, sha256 };
